'use strict';

const fs = require('fs');

const n = Number(fs.readFileSync(0, 'utf8').trim());
const MOD = 1000003;

function modPow(base, exponent) {
    let result = 1;
    while (exponent > 0) {
        if (exponent % 2 === 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exponent = Math.floor(exponent / 2);
    }
    return result;
}

console.log(n <= 1 ? 1 : modPow(3, n - 1));

